import React, { useState } from 'react';
import { FiUpload, FiCheck, FiFile, FiX } from 'react-icons/fi';
import Header from '../components/Header';
import Footer from '../components/Footer';
import toast from 'react-hot-toast';

const UploadPrescription = () => {
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [uploaded, setUploaded] = useState(false);
  const [notes, setNotes] = useState('');

  const handleFileChange = (e) => {
    const newFiles = Array.from(e.target.files);
    const validFiles = newFiles.filter((f) => f.type === 'image/jpeg' || f.type === 'image/png' || f.type === 'application/pdf');
    if (validFiles.length !== newFiles.length) {
      toast.error('Only JPEG, PNG, and PDF files are allowed');
    }
    setFiles((prev) => [...prev, ...validFiles].slice(0, 5));
  };

  const removeFile = (index) => {
    setFiles(files.filter((_, i) => i !== index));
  };

  const handleUpload = async () => {
    if (files.length === 0) {
      toast.error('Please upload at least one file');
      return;
    }
    setUploading(true);
    await new Promise((resolve) => setTimeout(resolve, 2000));
    setUploading(false);
    setUploaded(true);
    toast.success('Prescription uploaded successfully!');
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <main style={{ flex: 1 }}>
        <div className="container page-wrapper">
          <div style={{ maxWidth: '700px', margin: '0 auto' }}>
            <h1 style={{ fontSize: '22px', fontWeight: 700, marginBottom: '8px' }}>Upload Prescription</h1>
            <p style={{ fontSize: '14px', color: 'var(--text-light)', marginBottom: '24px' }}>Upload your eye prescription and we'll help you find the perfect lenses</p>

            {uploaded ? (
              <div className="card" style={{ padding: '40px', textAlign: 'center' }}>
                <div style={{ width: '64px', height: '64px', borderRadius: '50%', background: 'var(--success-light)', color: 'var(--success)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
                  <FiCheck size={28} />
                </div>
                <h3 style={{ fontSize: '18px', fontWeight: 600, marginBottom: '8px' }}>Prescription Uploaded!</h3>
                <p style={{ fontSize: '14px', color: 'var(--text-secondary)', marginBottom: '24px' }}>Our team will review your prescription and get back to you within 24 hours.</p>
                <button onClick={() => { setUploaded(false); setFiles([]); setNotes(''); }} className="btn btn-primary">Upload Another</button>
              </div>
            ) : (
              <div className="card" style={{ padding: '24px' }}>
                <div style={{ border: '2px dashed var(--border)', borderRadius: '8px', padding: '40px', textAlign: 'center', marginBottom: '20px', cursor: 'pointer', transition: 'border-color 0.2s' }} onClick={() => document.getElementById('fileInput').click()}>
                  <FiUpload size={40} style={{ color: 'var(--primary)', marginBottom: '12px' }} />
                  <h3 style={{ fontSize: '16px', fontWeight: 500, marginBottom: '8px' }}>Click to upload or drag and drop</h3>
                  <p style={{ fontSize: '13px', color: 'var(--text-light)' }}>JPEG, PNG, or PDF (Max 5 files, 5MB each)</p>
                  <input id="fileInput" type="file" multiple accept=".jpg,.jpeg,.png,.pdf" onChange={handleFileChange} style={{ display: 'none' }} />
                </div>

                {files.length > 0 && (
                  <div style={{ marginBottom: '20px' }}>
                    <h4 style={{ fontSize: '14px', fontWeight: 600, marginBottom: '8px' }}>Uploaded Files ({files.length})</h4>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                      {files.map((file, idx) => (
                        <div key={idx} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 12px', background: 'var(--bg-primary)', borderRadius: '4px' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                            <FiFile size={16} style={{ color: 'var(--primary)' }} />
                            <span style={{ fontSize: '13px' }}>{file.name}</span>
                            <span style={{ fontSize: '12px', color: 'var(--text-light)' }}>({(file.size / 1024).toFixed(1)} KB)</span>
                          </div>
                          <button onClick={() => removeFile(idx)} style={{ color: 'var(--danger)', cursor: 'pointer', background: 'none' }}><FiX size={16} /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="input-group" style={{ marginBottom: '20px' }}>
                  <label>Additional Notes (optional)</label>
                  <textarea className="input" rows={3} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Any special instructions or lens preferences..." />
                </div>

                <button onClick={handleUpload} disabled={uploading || files.length === 0} className="btn btn-primary btn-lg btn-block">
                  {uploading ? <div className="spinner" style={{ width: '18px', height: '18px', borderWidth: '2px' }} /> : 'Upload Prescription'}
                </button>
              </div>
            )}

            <div className="card" style={{ padding: '20px', marginTop: '24px' }}>
              <h3 style={{ fontSize: '16px', fontWeight: 600, marginBottom: '12px' }}>What to include in your prescription</h3>
              <ul style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {['Sphere (SPH) power for each eye', 'Cylinder (CYL) power if you have astigmatism', 'Axis for cylinder correction', 'Addition (ADD) power for reading/bifocals', 'Pupillary Distance (PD)'].map((item, idx) => (
                  <li key={idx} style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--text-secondary)' }}>
                    <FiCheck size={14} style={{ color: 'var(--success)', flexShrink: 0 }} /> {item}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default UploadPrescription;
